//! TLS: a certificate generated by the server, one uploaded by the
//! administrator, or one obtained and renewed by ACME (`acme.rs`). The
//! listener's certificate sits in a [`CertSlot`] so that changing the TLS
//! settings swaps it without restarting the listener.

use crate::config::{Config, TlsMode};
use anyhow::{Context, Result, bail};
use parking_lot::RwLock;
use rustls::pki_types::pem::PemObject;
use rustls::pki_types::{CertificateDer, PrivateKeyDer};
use rustls::server::{ClientHello, ResolvesServerCert};
use rustls::sign::CertifiedKey;
use std::path::{Path, PathBuf};
use std::sync::Arc;

/// Install the `ring` provider as the process default (idempotent).
pub fn install_crypto_provider() {
    let _ = rustls::crypto::ring::default_provider().install_default();
}

/// The certificate the server presents, for display: fixed, or renewed by
/// ACME.
#[derive(Clone)]
pub enum Presented {
    Fixed(String),
    Acme(Arc<crate::acme::Acme>),
}

impl Presented {
    pub fn fingerprint(&self) -> String {
        match self {
            Self::Fixed(fp) => fp.clone(),
            Self::Acme(acme) => acme.fingerprint(),
        }
    }
}

/// Upper-case colon-separated SHA-256 of a DER certificate.
pub fn fingerprint(der: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    Sha256::digest(der)
        .iter()
        .map(|b| format!("{b:02X}"))
        .collect::<Vec<_>>()
        .join(":")
}

/// The certificate source the listener asks on every handshake.
#[derive(Debug)]
pub struct CertSlot {
    inner: RwLock<Arc<dyn ResolvesServerCert>>,
}

impl CertSlot {
    pub fn new(resolver: Arc<dyn ResolvesServerCert>) -> Arc<Self> {
        Arc::new(Self {
            inner: RwLock::new(resolver),
        })
    }

    pub fn set(&self, resolver: Arc<dyn ResolvesServerCert>) {
        *self.inner.write() = resolver;
    }
}

impl ResolvesServerCert for CertSlot {
    fn resolve(&self, hello: ClientHello<'_>) -> Option<Arc<CertifiedKey>> {
        let resolver = Arc::clone(&self.inner.read());
        resolver.resolve(hello)
    }
}

/// A fixed certificate.
#[derive(Debug)]
struct Fixed(Arc<CertifiedKey>);

impl ResolvesServerCert for Fixed {
    fn resolve(&self, _: ClientHello<'_>) -> Option<Arc<CertifiedKey>> {
        Some(Arc::clone(&self.0))
    }
}

/// No certificate (the listener serves plain HTTP behind a proxy).
#[derive(Debug)]
struct NoCertificate;

impl ResolvesServerCert for NoCertificate {
    fn resolve(&self, _: ClientHello<'_>) -> Option<Arc<CertifiedKey>> {
        None
    }
}

pub fn no_certificate() -> Arc<dyn ResolvesServerCert> {
    Arc::new(NoCertificate)
}

/// The rustls configuration of the HTTPS listener (also answers ACME
/// TLS-ALPN-01 when the slot holds an ACME resolver).
pub fn server_config(slot: Arc<CertSlot>) -> Result<Arc<rustls::ServerConfig>> {
    let provider = Arc::new(rustls::crypto::ring::default_provider());
    let mut config = rustls::ServerConfig::builder_with_provider(provider)
        .with_protocol_versions(&[&rustls::version::TLS13, &rustls::version::TLS12])
        .context("TLS versions")?
        .with_no_client_auth()
        .with_cert_resolver(slot);
    config.alpn_protocols = vec![b"http/1.1".to_vec(), crate::acme::ACME_TLS_ALPN.to_vec()];
    Ok(Arc::new(config))
}

/// The rustls configuration of TURN over TLS: the web certificate, no ALPN
/// (clients offer none or `stun.turn`).
pub fn turns_config(slot: Arc<CertSlot>) -> Result<Arc<rustls::ServerConfig>> {
    let provider = Arc::new(rustls::crypto::ring::default_provider());
    let config = rustls::ServerConfig::builder_with_provider(provider)
        .with_protocol_versions(&[&rustls::version::TLS13, &rustls::version::TLS12])
        .context("TLS versions")?
        .with_no_client_auth()
        .with_cert_resolver(slot);
    Ok(Arc::new(config))
}

/// What the TLS settings resolve to.
pub struct Prepared {
    pub resolver: Arc<dyn ResolvesServerCert>,
    pub presented: Presented,
    /// The ACME manager, to be run once the listener answers.
    pub acme: Option<Arc<crate::acme::Acme>>,
}

/// The certificate for `cfg` (generating or loading it). `None` in proxy
/// mode.
pub fn prepare(cfg: &Config) -> Result<Option<Prepared>> {
    let dir = cfg.tls_dir();
    let (cert_path, key_path) = match cfg.tls.mode {
        TlsMode::Proxy => return Ok(None),
        TlsMode::Acme => {
            let acme = crate::acme::Acme::prepare(cfg)?;
            return Ok(Some(Prepared {
                resolver: acme.resolver(),
                presented: Presented::Acme(Arc::clone(&acme)),
                acme: Some(acme),
            }));
        }
        TlsMode::SelfSigned => ensure_self_signed(&dir, &self_signed_names(cfg))?,
        TlsMode::Provided => provided_paths(&dir),
    };
    let (key, fp) = load_pair(&cert_path, &key_path)?;
    Ok(Some(Prepared {
        resolver: Arc::new(Fixed(key)),
        presented: Presented::Fixed(fp),
        acme: None,
    }))
}

fn load_pair(cert_path: &Path, key_path: &Path) -> Result<(Arc<CertifiedKey>, String)> {
    let certs: Vec<CertificateDer<'static>> = CertificateDer::pem_file_iter(cert_path)
        .with_context(|| format!("reading {}", cert_path.display()))?
        .collect::<Result<_, _>>()
        .with_context(|| format!("parsing {}", cert_path.display()))?;
    if certs.is_empty() {
        bail!("{} contains no certificate", cert_path.display());
    }
    let key = PrivateKeyDer::from_pem_file(key_path)
        .with_context(|| format!("reading private key {}", key_path.display()))?;
    let fp = fingerprint(certs[0].as_ref());
    Ok((crate::acme::certified_key(certs, &key)?, fp))
}

/// Names on the self-signed certificate: the configured ones and the host
/// of `public_url`.
pub fn self_signed_names(cfg: &Config) -> Vec<String> {
    let mut names: Vec<String> = cfg
        .tls
        .hostnames
        .iter()
        .map(|h| h.trim().to_owned())
        .filter(|h| !h.is_empty())
        .collect();
    if let Some(host) = url::Url::parse(&cfg.public_url)
        .ok()
        .and_then(|u| u.host_str().map(|h| h.trim_matches(['[', ']']).to_owned()))
        && !names.contains(&host)
    {
        names.push(host);
    }
    if names.is_empty() {
        names.push("localhost".to_owned());
    }
    names
}

/// The uploaded certificate chain and key.
pub fn provided_paths(dir: &Path) -> (PathBuf, PathBuf) {
    (dir.join("provided-cert.pem"), dir.join("provided-key.pem"))
}

/// Check an uploaded certificate chain and key (they must match) and store
/// them; the certificate's fingerprint.
pub fn store_provided(dir: &Path, cert_pem: &str, key_pem: &str) -> Result<String> {
    let certs: Vec<CertificateDer<'static>> = CertificateDer::pem_slice_iter(cert_pem.as_bytes())
        .collect::<Result<_, _>>()
        .context("the certificate is not PEM")?;
    if certs.is_empty() {
        bail!("no certificate");
    }
    let key = PrivateKeyDer::from_pem_slice(key_pem.as_bytes()).context("the key is not PEM")?;
    let certified = crate::acme::certified_key(certs.clone(), &key)?;
    certified
        .keys_match()
        .context("the certificate and the key do not match")?;
    std::fs::create_dir_all(dir).with_context(|| format!("creating {}", dir.display()))?;
    let (cert_path, key_path) = provided_paths(dir);
    write_private(&key_path, key_pem.as_bytes())?;
    std::fs::write(&cert_path, cert_pem)
        .with_context(|| format!("writing {}", cert_path.display()))?;
    Ok(fingerprint(certs[0].as_ref()))
}

/// `cert.pem`/`key.pem` in `dir` for `names`: reused while they cover the
/// names, generated again otherwise (a new fingerprint).
pub fn ensure_self_signed(dir: &Path, names: &[String]) -> Result<(PathBuf, PathBuf)> {
    let cert_path = dir.join("cert.pem");
    let key_path = dir.join("key.pem");
    let names_path = dir.join("cert-names.json");
    let covered: Vec<String> = std::fs::read_to_string(&names_path)
        .ok()
        .and_then(|t| serde_json::from_str(&t).ok())
        .unwrap_or_default();
    if cert_path.exists() && key_path.exists() && names.iter().all(|n| covered.contains(n)) {
        return Ok((cert_path, key_path));
    }
    std::fs::create_dir_all(dir).with_context(|| format!("creating {}", dir.display()))?;
    let ck = rcgen::generate_simple_self_signed(names.to_vec()).context("generating certificate")?;
    write_private(&key_path, ck.signing_key.serialize_pem().as_bytes())?;
    std::fs::write(&cert_path, ck.cert.pem())
        .with_context(|| format!("writing {}", cert_path.display()))?;
    std::fs::write(&names_path, serde_json::to_string(names)?)?;
    tracing::info!(path = %cert_path.display(), ?names, "generated self-signed certificate");
    Ok((cert_path, key_path))
}

/// Write a private file (mode 0600 on Unix).
pub fn write_private(path: &Path, data: &[u8]) -> Result<()> {
    #[cfg(unix)]
    {
        use std::io::Write;
        use std::os::unix::fs::OpenOptionsExt;
        let mut f = std::fs::OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .mode(0o600)
            .open(path)
            .with_context(|| format!("writing {}", path.display()))?;
        f.write_all(data)?;
        Ok(())
    }
    #[cfg(not(unix))]
    {
        std::fs::write(path, data).with_context(|| format!("writing {}", path.display()))
    }
}
